// s5_expr.js - Expression evaluator with + - * / operations

function evaluate(expr) {
    // Remove all spaces
    expr = expr.replace(/\s/g, '');

    // Check for empty expression
    if (expr === '') {
        throw new Error('Empty expression');
    }

    // Check for invalid characters
    if (!/^[0-9+\-*/.()]+$/.test(expr)) {
        throw new Error('Invalid characters in expression');
    }

    // Check for invalid patterns
    if (expr.match(/[+\-*/]{2,}/) || expr.match(/^[+\-*/]|[+\-*/]$/)) {
        throw new Error('Invalid expression format');
    }

    // Handle division by zero
    if (expr.includes('/0')) {
        throw new Error('Division by zero');
    }

    // Simple evaluation using eval (for this exercise)
    // In a real implementation, we'd parse and evaluate properly
    try {
        // Replace division by zero cases
        if (expr.includes('/0')) {
            throw new Error('Division by zero');
        }

        // Use Function constructor to avoid direct eval
        const result = new Function('return ' + expr)();

        // Check if result is valid number
        if (typeof result !== 'number' || isNaN(result)) {
            throw new Error('Invalid expression');
        }

        return result;
    } catch (e) {
        throw new Error('Invalid expression');
    }
}

