def score(self, student, assignment):
    if student not in self.students or assignment not in self.assignments:
        return None
    if student not in self.scores or assignment not in self.scores[student]:
        return None
    return self.scores[student][assignment]

def percent(self, student):
    if student not in self.students:
        raise KeyError("Unknown student")

    if student not in self.scores:
        return None

    total_points = 0
    total_max_points = 0

    for assignment, points in self.scores[student].items():
        total_points += points
        total_max_points += self.assignment_max_points[assignment]

    if total_max_points == 0:
        return None

    return round((total_points / total_max_points) * 100, 2)

document.addEventListener('DOMContentLoaded', function() {
    const addButton = document.getElementById('s9-add');
    const inputField = document.getElementById('s9-new');
    const todoList = document.getElementById('s9-todo').querySelector('ul');
    const doingList = document.getElementById('s9-doing').querySelector('ul');
    const doneList = document.getElementById('s9-done').querySelector('ul');

    function createCard(text) {
        const li = document.createElement('li');
        li.className = 's9-card';
        li.textContent = text;

        // Create left and right buttons
        const leftButton = document.createElement('button');
        leftButton.className = 's9-left';
        leftButton.textContent = '←';
        leftButton.addEventListener('click', function(e) {
            e.stopPropagation();
            moveCard(li, -1);
        });

        const rightButton = document.createElement('button');
        rightButton.className = 's9-right';
        rightButton.textContent = '→';
        rightButton.addEventListener('click', function(e) {
            e.stopPropagation();
            moveCard(li, 1);
        });

        li.appendChild(leftButton);
        li.appendChild(rightButton);

        return li;
    }

    function moveCard(card, direction) {
        const currentList = card.parentElement;
        let targetList;

        if (direction === 1) {
            // Moving right
            if (currentList === todoList) {
                targetList = doingList;
            } else if (currentList === doingList) {
                targetList = doneList;
            } else {
                // Already in Done, do nothing
                return;
            }
        } else if (direction === -1) {
            // Moving left
            if (currentList === doingList) {
                targetList = todoList;
            } else if (currentList === doneList) {
                targetList = doingList;
            } else {
                // Already in To Do, do nothing
                return;
            }
        }

        if (targetList) {
            targetList.appendChild(card);
        }
    }

    addButton.addEventListener('click', function() {
        const text = inputField.value.trim();
        if (text) {
            const li = createCard(text);
            todoList.appendChild(li);
            inputField.value = '';
        }
    });

    inputField.addEventListener('keypress', function(e) {
        if (e.key === 'Enter') {
            addButton.click();
        }
    });
});

