  }
  if (!member || typeof member !== 'string') {
    throw new Error("Member must be a non-empty string");
  }

  // Check if book exists
  if (!this.books.has(isbn)) {
    throw new Error(`Book with ISBN ${isbn} not found`);
  }

  const book = this.books.get(isbn);

  // Check if member has this book
  if (!book.loans.has(member)) {
    throw new Error(`Member ${member} does not have book ${isbn}`);
  }

  // Return the book
  book.copies += 1;
  book.loans.delete(member);

  // If there are members waiting in the hold queue, give the book to the first one
  if (book.holds.length > 0) {
    const nextMember = book.holds.shift();
    book.copies -= 1;
    // The new loan starts on the day of return
    book.loans.set(nextMember, day);
  }
}

