    return undefined;
  }

  const entry = this.map.get(key);
  const { value, timestamp, ttl } = entry;

  // Check if entry has expired
  if (this.now() - timestamp > ttl) {
    this.map.delete(key);
    return undefined;
  }

  // Move to end to mark as recently used
  this.map.delete(key);
  this.map.set(key, entry);

  return value;
}

has(key) {
  if (!this.map.has(key)) {
    return false;
  }

  const entry = this.map.get(key);
  const { timestamp, ttl } = entry;

  // Check if entry has expired
  if (this.now() - timestamp > ttl) {
    this.map.delete(key);
    return false;
  }

  return true;
}

peek(key) {
  if (!this.map.has(key)) {
    return undefined;
  }

  const entry = this.map.get(key);
  const { value, timestamp, ttl } = entry;

  // Check if entry has expired
  if (this.now() - timestamp > ttl) {
    this.map.delete(key);
    return undefined;
  }

  // Return the value without marking as recently used
  return value;
}

size() {
