class Cache {
  constructor(capacity, options = {}) {
    if (!Number.isInteger(capacity) || capacity <= 0) {
      throw new Error("Capacity must be a positive integer");
    }

    this.capacity = capacity;
    this.map = new Map();
    this.ttl = options.ttl || Infinity;
    this.now = options.now || Date.now;

    // Stats counters
    this.hits = 0;
    this.misses = 0;
    this.evictions = 0;
    this.expirations = 0;
  }

get(key) {
  if (!this.map.has(key)) {
    this.misses++;
    return undefined;
  }

  const entry = this.map.get(key);
  const { value, timestamp, ttl } = entry;

  // Check if entry has expired
  if (this.now() - timestamp > ttl) {
    this.map.delete(key);
    this.expirations++;
    return undefined;
  }

  // Move to end to mark as recently used
  this.map.delete(key);
  this.map.set(key, entry);
  this.hits++;

  return value;
}

set(key, value, options = {}) {
  if (this.map.has(key)) {
    // Update existing key
    this.map.delete(key);
  } else if (this.map.size >= this.capacity) {
    // Remove least recently used item (first item in the map)
    const firstKey = this.map.keys().next().value;
    this.map.delete(firstKey);
    this.evictions++;
  }

  const ttl = options.ttl !== undefined ? options.ttl : this.ttl;
  const timestamp = this.now();

  this.map.set(key, { value, timestamp, ttl });
}

  keys() {
    return Array.from(this.map.keys()).reverse();
  }

  stats() {
    return {
      hits: this.hits,
      misses: this.misses,
      evictions: this.evictions,
      expirations: this.expirations
    };
  }
}

