        }
      } catch (e) {
        // Ignore errors in reconstruction
      }
    }

    // Rebuild holds
    for (const [isbn, members] of Object.entries(data.holds || {})) {
      if (library.books.has(isbn)) {
        const book = library.books.get(isbn);
        book.holds = [...members];
      }
