// Matrix class implementation
class Matrix {
  constructor(rows) {
    // Validate input
    if (!Array.isArray(rows)) {
      throw new Error("Rows must be an array");
    }

    if (rows.length === 0) {
      throw new Error("Matrix must have at least one row");
    }

    const firstRow = rows[0];
    if (!Array.isArray(firstRow)) {
      throw new Error("Each row must be an array");
    }

    if (firstRow.length === 0) {
      throw new Error("Matrix must have at least one column");
    }

    const cols = firstRow.length;
    for (let i = 0; i < rows.length; i++) {
      const row = rows[i];
      if (!Array.isArray(row)) {
        throw new Error("Each row must be an array");
      }
      if (row.length !== cols) {
        throw new Error("All rows must have the same length");
      }
      for (let j = 0; j < row.length; j++) {
        if (typeof row[j] !== 'number' || !isFinite(row[j])) {
          throw new Error("All entries must be finite numbers");
        }
      }
    }

    this._rows = rows;
  }

  shape() {
    return [this._rows.length, this._rows[0].length];
  }

  get(r, c) {
    if (r < 0 || r >= this._rows.length || c < 0 || c >= this._rows[0].length) {
      throw new Error("Index out of bounds");
    }
    return this._rows[r][c];
  }

  set(r, c, value) {
    if (r < 0 || r >= this._rows.length || c < 0 || c >= this._rows[0].length) {
      throw new Error("Index out of bounds");
    }
    if (typeof value !== 'number' || !isFinite(value)) {
      throw new Error("Value must be a finite number");
    }
    this._rows[r][c] = value;
  }

  // Matrix addition
  add(other) {
    if (this._rows.length !== other._rows.length || this._rows[0].length !== other._rows[0].length) {
      throw new Error("Matrices must have the same dimensions for addition");
    }

    const resultRows = [];
    for (let i = 0; i < this._rows.length; i++) {
      const resultRow = [];
      for (let j = 0; j < this._rows[i].length; j++) {
        resultRow.push(this._rows[i][j] + other._rows[i][j]);
      }
      resultRows.push(resultRow);
    }

    return new Matrix(resultRows);
  }

  // Matrix multiplication
  multiply(other) {
    if (this._rows[0].length !== other._rows.length) {
      throw new Error("Number of columns in first matrix must equal number of rows in second matrix");
    }

    const resultRows = [];
    for (let i = 0; i < this._rows.length; i++) {
      const resultRow = [];
      for (let j = 0; j < other._rows[0].length; j++) {
        let sum = 0;
        for (let k = 0; k < this._rows[i].length; k++) {
          sum += this._rows[i][k] * other._rows[k][j];
        }
        resultRow.push(sum);
      }
      resultRows.push(resultRow);
    }

    return new Matrix(resultRows);
  }

  // Matrix transpose
  transpose() {
    const resultRows = [];
    for (let j = 0; j < this._rows[0].length; j++) {
      const resultRow = [];
      for (let i = 0; i < this._rows.length; i++) {
        resultRow.push(this._rows[i][j]);
      }
      resultRows.push(resultRow);
    }

    return new Matrix(resultRows);
  }

  // Calculate determinant
  determinant() {
    const rows = this._rows;
    const n = rows.length;

    if (n !== rows[0].length) {
      throw new Error("Determinant can only be calculated for square matrices");
    }

    if (n === 1) {
      return rows[0][0];
    }

    if (n === 2) {
      return rows[0][0] * rows[1][1] - rows[0][1] * rows[1][0];
    }

    // For larger matrices, use cofactor expansion along the first row
    let det = 0;
    for (let j = 0; j < n; j++) {
      // Create minor matrix by removing row 0 and column j
      const minorRows = [];
      for (let i = 1; i < n; i++) {
        const minorRow = [];
        for (let k = 0; k < n; k++) {
          if (k !== j) {
            minorRow.push(rows[i][k]);
          }
        }
        minorRows.push(minorRow);
      }

      const minor = new Matrix(minorRows);
      const sign = (j % 2 === 0) ? 1 : -1;
      det += sign * rows[0][j] * minor.determinant();
    }

    return det;
  }

  // Calculate inverse
  inverse() {
    const rows = this._rows;
    const n = rows.length;

    if (n !== rows[0].length) {
      throw new Error("Inverse can only be calculated for square matrices");
    }

    const det = this.determinant();
    if (Math.abs(det) < 1e-10) {
      throw new Error("Matrix is singular (determinant is zero)");
    }

    // For 2x2 matrix
    if (n === 2) {
      const a = rows[0][0], b = rows[0][1], c = rows[1][0], d = rows[1][1];
      const invDet = 1 / det;
      return new Matrix([
        [d * invDet, -b * invDet],
        [-c * invDet, a * invDet]
      ]);
    }

    // For larger matrices, use cofactor method
    const cofactorRows = [];
    for (let i = 0; i < n; i++) {
      const cofactorRow = [];
      for (let j = 0; j < n; j++) {
        // Create minor matrix by removing row i and column j
        const minorRows = [];
        for (let k = 0; k < n; k++) {
          if (k !== i) {
            const minorRow = [];
            for (let l = 0; l < n; l++) {
              if (l !== j) {
                minorRow.push(rows[k][l]);
              }
            }
            minorRows.push(minorRow);
          }
        }

        const minor = new Matrix(minorRows);
        const sign = ((i + j) % 2 === 0) ? 1 : -1;
        cofactorRow.push(sign * minor.determinant());
      }
      cofactorRows.push(cofactorRow);
    }

    const cofactorMatrix = new Matrix(cofactorRows);
    const adjoint = cofactorMatrix.transpose();
    const invDet = 1 / det;

    const resultRows = [];
    for (let i = 0; i < n; i++) {
      const resultRow = [];
      for (let j = 0; j < n; j++) {
        resultRow.push(adjoint._rows[i][j] * invDet);
      }
      resultRows.push(resultRow);
    }

    return new Matrix(resultRows);
  }

  // Solve linear system Ax = b
  solve(b) {
    const rows = this._rows;
    const n = rows.length;

    // Validate input
    if (n !== rows[0].length) {
      throw new Error("Matrix must be square to solve linear system");
    }

    if (b.length !== n) {
      throw new Error("Vector b must have the same number of elements as matrix rows");
    }

    // Create augmented matrix [A|b]
    const augmentedRows = [];
    for (let i = 0; i < n; i++) {
      const augmentedRow = [...rows[i], b[i]];
      augmentedRows.push(augmentedRow);
    }

    const augmentedMatrix = new Matrix(augmentedRows);

    // Forward elimination
    for (let i = 0; i < n; i++) {
      // Find pivot
      let maxRow = i;
      for (let k = i + 1; k < n; k++) {
        if (Math.abs(augmentedMatrix._rows[k][i]) > Math.abs(augmentedMatrix._rows[maxRow][i])) {
          maxRow = k;
        }
      }

      // Swap rows if needed
      if (maxRow !== i) {
        [augmentedMatrix._rows[i], augmentedMatrix._rows[maxRow]] = [augmentedMatrix._rows[maxRow], augmentedMatrix._rows[i]];
      }

      // Check for singular matrix
      if (Math.abs(augmentedMatrix._rows[i][i]) < 1e-10) {
        throw new Error("Matrix is singular (cannot solve linear system)");
      }

      // Eliminate column
      for (let k = i + 1; k < n; k++) {
        const factor = augmentedMatrix._rows[k][i] / augmentedMatrix._rows[i][i];
        for (let j = i; j <= n; j++) {
          augmentedMatrix._rows[k][j] -= factor * augmentedMatrix._rows[i][j];
        }
      }
    }

    // Back substitution
    const x = new Array(n);
    for (let i = n - 1; i >= 0; i--) {
      x[i] = augmentedMatrix._rows[i][n];
      for (let j = i + 1; j < n; j++) {
        x[i] -= augmentedMatrix._rows[i][j] * x[j];
      }
      x[i] /= augmentedMatrix._rows[i][i];
    }

    return x;
  }

  // Check if two matrices are equal
  equals(other) {
    if (this._rows.length !== other._rows.length || this._rows[0].length !== other._rows[0].length) {
      return false;
    }

    for (let i = 0; i < this._rows.length; i++) {
      for (let j = 0; j < this._rows[i].length; j++) {
        if (this._rows[i][j] !== other._rows[i][j]) {
          return false;
        }
      }
    }

    return true;
  }
}

