        } else if (token.type === 'lparen') {
            operatorStack.push(token.value);
        } else if (token.type === 'rparen') {
            while (operatorStack.length > 0 && operatorStack[operatorStack.length - 1] !== 'lparen') {
                output.push(operatorStack.pop());
